(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;if(root)root.STS_CLIMATE_HISTORY=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=(l,en,bn)=>l==='bn'?bn:en;
let pending=null;
function load(){if(!pending)pending=fetch('/data/climate-history.json').then(r=>{if(!r.ok)throw Error('Local weather file unavailable');return r.json();}).then(d=>{if(d.schema!=='ui-climate-history.v1'||d.districts.length!==64)throw Error('Invalid weather file');return d;}).catch(e=>{pending=null;throw e;});return pending;}
function seasonal(m,metric,lang){
 if(!m.seasonal_profile)return '';
 const monthNames=Array.from({length:12},(_,i)=>new Intl.DateTimeFormat(lang==='bn'?'bn-BD':'en-GB',{month:'short',timeZone:'UTC'}).format(new Date(Date.UTC(2020,i,1))));
 const values=m.seasonal_profile.flatMap(row=>row.periods.map(p=>p.mean)).filter(v=>v!==null);const max=Math.max(1,...values),unit=metric==='T2M'?'°C':'mm/month';
 return `<section class="seasonal-profile"><h3>${t(lang,'How the seasons changed','ঋতু অনুযায়ী পরিবর্তন')}</h3><p>2001–2010 <span class="season-key early">●</span> · 2016–2025 <span class="season-key recent">●</span> · ${unit}</p><div class="seasonal-plot"><div class="seasonal-scale" aria-hidden="true"><span>${max.toFixed(0)}</span><span>${(max/2).toFixed(0)}</span><span>0</span></div><div class="seasonal-bars" role="img" aria-label="${t(lang,'Monthly historical comparison, values available in the table below','মাসিক ঐতিহাসিক তুলনা, নিচের সারণিতে মান আছে')}">${m.seasonal_profile.map((row,i)=>`<div class="season-month"><div class="season-pair">${row.periods.map((p,j)=>`<i class="${j?'recent':'early'}" style="height:${p.mean===null?0:Math.max(0,p.mean/max*100)}%" title="${p.start}–${p.end}: ${p.mean??'missing'} ${unit}"></i>`).join('')}</div><small>${monthNames[i]}</small></div>`).join('')}</div></div><details><summary>${t(lang,'Monthly values and coverage','মাসিক মান ও প্রাপ্যতা')}</summary><table><caption>${t(lang,'Mean monthly values; ten complete observations required per period','মাসিক গড়; প্রতি সময়ে দশটি পূর্ণ মান প্রয়োজন')}</caption><thead><tr><th>${t(lang,'Month','মাস')}</th><th>2001–2010 (${unit})</th><th>2016–2025 (${unit})</th></tr></thead><tbody>${m.seasonal_profile.map((row,i)=>`<tr><th>${monthNames[i]}</th>${row.periods.map(p=>`<td>${p.mean===null?'Missing':p.mean.toFixed(2)} · ${p.valid_months}/10</td>`).join('')}</tr>`).join('')}</tbody></table></details><p class="weather-note">${t(lang,'Shared scale within each metric. Monthly rainfall totals and monthly mean temperatures; descriptive context, not crop requirements.','প্রতি পরিমাপকে একই স্কেল। মাসিক মোট বৃষ্টি ও গড় তাপমাত্রা; এটি ফসলের চাহিদা নয়।')}</p></section>`;
}
function render(bundle,id,metric='T2M',lang='en',chart){
 const label=t(lang,'Choose a district','জেলা বেছে নিন');
 if(!bundle)return `<p role="status">${t(lang,'Loading local NASA weather history…','স্থানীয় নাসা আবহাওয়ার ইতিহাস লোড হচ্ছে…')}</p>`;
 const d=bundle.districts.find(d=>d.id===id),grid=d&&bundle.grids[d.grid],m=grid?.metrics[metric];
 const chooser=`<label for="weather-district">${label}</label><select id="weather-district" data-weather-district><option value="">${label}</option>${bundle.districts.map(d=>`<option value="${esc(d.id)}" ${d.id===id?'selected':''}>${esc(lang==='bn'?d.bn:d.en)}</option>`).join('')}</select>`;
 const controls=`<div class="weather-controls">${chooser}<div role="group" aria-label="${t(lang,'Weather metric','আবহাওয়ার পরিমাপক')}">${[['T2M','Temperature','তাপমাত্রা'],['PRECTOTCORR','Rainfall','বৃষ্টিপাত']].map(([key,en,bn])=>`<button type="button" data-weather-metric="${key}" aria-pressed="${metric===key}">${t(lang,en,bn)}</button>`).join('')}</div></div>`;
 if(!m)return `${controls}<p class="weather-note">${t(lang,'Select any of the 64 districts to explore its representative NASA grid point. No district is selected for you.','৬৪টি জেলার যেকোনো একটি বেছে নাসার প্রতিনিধিত্বকারী গ্রিড পয়েন্ট দেখুন। কোনো জেলা আগে থেকে বাছাই করা নেই।')}</p>`;
 const fmt=v=>typeof v==='number'?v.toFixed(2):t(lang,'Missing','অনুপস্থিত');
 const series={label:t(lang,metric==='T2M'?'Annual mean air temperature':'Annual rainfall total',metric==='T2M'?'বার্ষিক গড় বায়ুর তাপমাত্রা':'বার্ষিক মোট বৃষ্টিপাত'),unit:m.unit,labels:m.annual.map(v=>String(v.year)),values:m.annual.map(v=>v.value)};
 const figures=`<div class="weather-periods">${m.periods.map(p=>`<article><small>${p.start}–${p.end}</small><strong>${fmt(p.mean)} <small>${esc(m.unit)}</small></strong><span>${p.valid_years}/10 ${t(lang,'complete years','পূর্ণ বছর')}</span></article>`).join('')}<article><small>${t(lang,'Later minus earlier','পরের গড় বিয়োগ আগের গড়')}</small><strong>${m.difference>0?'+':''}${fmt(m.difference)} <small>${esc(m.unit)}</small></strong><span>${t(lang,'Descriptive difference','বর্ণনামূলক পার্থক্য')}</span></article></div>`;
 return `${controls}<p class="weather-note">${t(lang,'Historical descriptive context · independent scientific review pending','ঐতিহাসিক বর্ণনামূলক প্রেক্ষাপট · স্বাধীন বৈজ্ঞানিক পর্যালোচনা বাকি')}</p><p class="weather-source">NASA POWER · ${esc(d.en)} · ${t(lang,'grid point','গ্রিড পয়েন্ট')} ${grid.latitude}° N, ${grid.longitude}° E · ${d.distance_km} km ${t(lang,'from district anchor','জেলার প্রতিনিধি অবস্থান থেকে')}</p>${figures}<h3>${esc(series.label)} · 2001–2025</h3>${chart?chart(series,lang):''}${seasonal(m,metric,lang)}<p class="weather-note">${t(lang,'Equal ten-year periods; annual values, not a forecast or a statistically significant trend claim. Temperature uses day-weighted monthly means; rainfall sums complete monthly totals.','সমান দশ বছরের গড়ের তুলনা; এটি পূর্বাভাস বা পরিসংখ্যানগত তাৎপর্যপূর্ণ প্রবণতার দাবি নয়। তাপমাত্রা দিনসংখ্যা অনুযায়ী মাসিক গড় থেকে এবং বৃষ্টিপাত পূর্ণ মাসের যোগফল থেকে হিসাব করা হয়েছে।')}</p><details><summary>${t(lang,'Source, method and limitations','উৎস, পদ্ধতি ও সীমাবদ্ধতা')}</summary><p>${esc(bundle.method)}</p><p>${esc(bundle.limitations)}</p><p>LST · ${esc(bundle.collection_id)}</p><p>${t(lang,'Archived NASA data; not a farm measurement. Grid context is independent of crop suitability.','সংরক্ষিত নাসা তথ্য; জমির সরাসরি পরিমাপ নয়। গ্রিডের প্রেক্ষাপট ফসলের উপযোগিতা নির্ধারণ করে না।')}</p><p><a href="${esc(bundle.source_url)}" target="_blank" rel="noopener">NASA POWER documentation ↗</a></p><small>Archive SHA-256: <code>${esc(bundle.archive_sha256)}</code><br>Chart SHA-256: <code>${esc(m.chart_sha256)}</code></small></details>`;
}
return {load,render};
});
